import pytest


def shout(xs: list[str]) -> None:
    """Print each string in xs upper-cased, one per line."""
    for s in xs:
        print(s.upper())


def test_shout_basic(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["hello", "World"])
    assert capsys.readouterr().out == "HELLO\nWORLD\n"


def test_shout_empty(capsys: pytest.CaptureFixture[str]) -> None:
    shout([])
    assert capsys.readouterr().out == ""


def test_shout_already_upper_and_mixed(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["ABC", "a1b2", "", "x y"])
    assert capsys.readouterr().out == "ABC\nA1B2\n\nX Y\n"


def test_shout_single(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["a"])
    assert capsys.readouterr().out == "A\n"


def test_shout_does_not_mutate_input(capsys: pytest.CaptureFixture[str]) -> None:
    xs = ["a", "b"]
    shout(xs)
    capsys.readouterr()
    assert xs == ["a", "b"]
